// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 blockNumMod, uint256 payment, uint32 timeIncrement) public {
        // keep block num small, assume payment in wide admissible range
        vm.assume(blockNumMod < 15);
        vm.assume(payment >= 0.1 ether && payment <= 100 ether);
        vm.assume(timeIncrement >= 1 && timeIncrement <= 365 days);

        // set up a clean block with block.timestamp > pastBlockTime
        uint256 initialTime = block.timestamp;
        vm.roll(block.number + uint256(blockNumMod) + 1);
        vm.warp(initialTime + timeIncrement);

        // record state before fallback
        uint256 balBefore = address(c).balance;
        uint256 timeBefore = c.pastBlockTime();

        address actor = address(0xdead);
        vm.deal(actor, payment);

        bool ok = false;
        vm.prank(actor);
        try c.fallback{value: payment}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;
        uint256 timeAfter = c.pastBlockTime();

        // assert general rule: if fallback succeeded, balance increase equals payment,
        // and pastBlockTime updates correctly.
        if (ok) {
            assertTrue(balAfter - balBefore == payment);
            assertTrue(timeAfter > timeBefore);
        } else {
            // revert leaves state unchanged
            assertTrue(balAfter == balBefore);
            assertTrue(timeAfter == timeBefore);
        }
    }
}

