pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 sendValue, uint256 warpTime, uint256 blockNum) public {
        // Restrict to admissible domain: sendValue <= address(this).balance to avoid deal failures, etc.
        vm.assume(sendValue <= type(uint128).max);
        vm.assume(warpTime > 0 && warpTime < type(uint64).max); // reasonable warp
        vm.assume(blockNum > 0 && blockNum < type(uint64).max);

        // Ensure block.timestamp > pastBlockTime (which is 0 initially)
        vm.warp(warpTime);
        vm.roll(blockNum);

        // Setup balance for the fallback call
        uint256 initialBalance = 100 ether;
        vm.deal(address(this), initialBalance + sendValue);

        // Record state before fallback
        uint256 balanceBefore = address(c).balance;
        uint256 pastTimeBefore = c.pastBlockTime();

        // Call fallback with fuzzed value
        (bool success, ) = address(c).call{value: sendValue}("");

        // If call fails, pastBlockTime shouldn't have changed (require failed)
        bool pastTimeUpdated = c.pastBlockTime() != pastTimeBefore;

        if (!success) {
            // Revert means no state change -> invariant trivially holds
            assertTrue(true);
            return;
        }

        // If call succeeded, pastBlockTime must have been updated (require passed)
        assertTrue(pastTimeUpdated);

        // The core invariant: balance can only change if block.number % 15 == 0 AND msg.value == 10 ether
        // In reference, balance changes iff (blockNum % 15 == 0 && sendValue == 10 ether)
        // In mutant, balance changes iff (blockNum % 15 == 0), regardless of sendValue
        uint256 balanceAfter = address(c).balance;
        bool balanceChanged = balanceAfter != balanceBefore;

        if (sendValue == 10 ether && blockNum % 15 == 0) {
            // Reference: balance should be 0 (drained); mutant: also 0
            // Both behave identically here.
            assertTrue(true);
        } else if (sendValue != 10 ether && blockNum % 15 == 0) {
            // Reference: require(msg.value == 10 ether) fails -> call reverts, but we already handled revert case.
            // Actually, if sendValue != 10 ether, reference reverts, so success==false -> we returned above.
            // This branch is unreachable for reference; for mutant, success==true and balance changes.
            // The invariant difference: mutant changes balance when it shouldn't.
            assertTrue(balanceChanged);
        } else {
            // blockNum % 15 != 0 -> no transfer in either version
            assertTrue(!balanceChanged);
        }
    }
}

