pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 blockNum1, uint256 blockNum2, uint256 warp1, uint256 warp2) public {
        // Restrict to block numbers that enable the transfer condition for both calls
        bound(blockNum1, 1, type(uint256).max - 1);
        vm.assume(blockNum1 % 15 == 0);
        bound(blockNum2, blockNum1 + 1, type(uint256).max);
        vm.assume(blockNum2 % 15 == 0);

        // Ensure timestamps are strictly increasing to distinguish the bug
        bound(warp1, 1, type(uint256).max - 2);
        bound(warp2, warp1, type(uint256).max - 1);
        // The second timestamp must be ≤ pastBlockTime after the first call to trigger the difference
        vm.assume(warp2 == warp1);

        // Fund the contract with 10 ether for the first call
        vm.deal(address(12345), 10 ether);
        vm.prank(address(12345));
        vm.roll(blockNum1);
        vm.warp(warp1);
        c.fallback{value: 10 ether}();
        // After first call, pastBlockTime = warp1, balance should be 20 ether (10 from setup + 10 from call)
        // The reference requires block.timestamp > pastBlockTime for the second call,
        // so it should revert when warp2 == warp1, while the mutant allows it.

        // Fund another account for the second call
        vm.deal(address(67890), 10 ether);
        vm.prank(address(67890));
        vm.roll(blockNum2);
        vm.warp(warp2);

        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // If the second call succeeded (ok == true), the buggy contract allowed it and transferred the balance,
        // leaving the contract with zero ether. The reference would have reverted (ok == false),
        // leaving the balance at 20 ether. Thus, for the reference, ok must be false; for the mutant, ok can be true.
        assertTrue(!ok);
    }
}

