pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 targetTimestamp) public {
        // Admissible domain: timestamp > 0 and within reasonable bounds
        vm.assume(targetTimestamp > 0 && targetTimestamp <= type(uint64).max);

        // Deploy adversarial helper that re-enters during transfer
        ReentrantAttacker attacker = new ReentrantAttacker();
        vm.deal(address(attacker), 10 ether);

        // Set block.number so that block.number % 15 == 0 to trigger transfer
        vm.roll(15);
        // Warp to a future timestamp that satisfies the require in the reference
        vm.warp(targetTimestamp);

        // Attacker triggers fallback with exactly 10 ether; during transfer, it re-enters
        attacker.attack(address(c), targetTimestamp);

        // After the call, pastBlockTime must be strictly less than the current block.timestamp.
        // In the reference, reentrant call fails because it violates block.timestamp > pastBlockTime,
        // leaving pastBlockTime = targetTimestamp - 1 (from the attack callback). In the mutant,
        // the reentrant call succeeds and sets pastBlockTime = targetTimestamp (current block.timestamp),
        // violating the invariant.
        assertTrue(c.pastBlockTime() < block.timestamp);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public attackTimestamp;

    function attack(address _target, uint256 _attackTimestamp) external payable {
        target = C(_target);
        attackTimestamp = _attackTimestamp;
        // First call: send exactly 10 ether, which will trigger transfer back to us (since block.number % 15 == 0)
        (bool success, ) = address(target).call{value: 10 ether}("");
        require(success, "first call failed");
    }

    receive() external payable {
        // Re-enter the target during the transfer with another 10 ether call
        // This will try to set pastBlockTime again, but in the reference the require(block.timestamp > pastBlockTime) will fail
        // because pastBlockTime was already set to attackTimestamp - 1 by the first call (warp was set to attackTimestamp before call,
        // so block.timestamp == attackTimestamp; pastBlockTime was set to block.timestamp = attackTimestamp) but we warp inside? No, we don't warp.
        // Actually, the first call sets pastBlockTime = attackTimestamp (block.timestamp). The reentrant call's block.timestamp is also attackTimestamp,
        // so require(block.timestamp > pastBlockTime) fails. In mutant, it succeeds and sets pastBlockTime = attackTimestamp again (or later).
        // To make it fail the invariant, we need the reentrant call to succeed in mutant, setting pastBlockTime to current block.timestamp.
        // But if block.timestamp hasn't changed, both are equal. The invariant says pastBlockTime < block.timestamp must hold after the call.
        // In mutant, after the outer call finishes, pastBlockTime will be block.timestamp from the inner reentrant call, so pastBlockTime == block.timestamp.
        (bool success, ) = address(target).call{value: 10 ether}("");
        // We don't care about success; the attack just needs to execute.
    }
}

