pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber) public {
        // Admissible domain: blockNumber > 0 so we can mine blocks
        vm.assume(blockNumber > 0);
        vm.assume(blockNumber < type(uint256).max / 2);

        // Ensure we are at a block where the first call's transfer does NOT happen (to keep balance)
        vm.roll(blockNumber);
        // Use same timestamp for both calls to trigger the bug
        vm.warp(1000);

        // First fallback call with 10 ether from an externally owned address
        address actor = address(0x1234);
        vm.deal(actor, 100 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Now we need the second call to be at a block.number where transfer triggers.
        // Without the require, the second call at the same timestamp can succeed.
        // We roll to a block where block.number % 15 == 0 to force the transfer.
        // The fuzzer will vary blockNumber; we compute the next block that satisfies the condition.
        uint256 nextBlock = block.number + 1;
        // Bound nextBlock to prevent overflow
        vm.assume(nextBlock < type(uint256).max / 2);
        while (nextBlock % 15 != 0) {
            nextBlock++;
            vm.assume(nextBlock < type(uint256).max / 2);
        }
        vm.roll(nextBlock);
        // Keep timestamp the same as before (1000)
        vm.warp(1000);

        // Actor sends another 10 ether
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // General rule: After two successful fallback calls with exactly 10 ether at the same timestamp,
        // the reference ensures the second call reverts (balance stays 10), while the mutant allows it.
        // Since the mutant allows the second call and it triggers a transfer (when block.number % 15 == 0),
        // the contract's balance becomes 0 instead of remaining at least 10 ether.
        // The reference would have reverted on the second call, so balance remains 10.
        // Therefore, the invariant: balance must be at least 10 ether after two such calls.
        // The reference holds (10 >= 10), the bug breaks (0 >= 10 is false).
        assertTrue(address(c).balance >= 10 ether);
    }
}

