pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 blockNumMod, uint256 warpAmount, uint256 actorSeed) public {
        // Restrict block number to a range where mod 15 can hit 0, but keep it wide
        vm.assume(blockNumMod < 200);
        vm.assume(warpAmount > 0);

        // Deploy a helper callee that can receive Ether and we can check its balance
        Collector collector = new Collector();
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        // Actor must be different from the deployed collector to avoid confusion
        vm.assume(actor != address(collector));

        // Warp to some future timestamp to satisfy require(block.timestamp > pastBlockTime)
        // pastBlockTime initially 0, so any positive warp is fine
        vm.warp(block.timestamp + 1 + warpAmount);

        // Set block number, possibly satisfying block.number % 15 == 0
        vm.roll(blockNumMod);

        // Give actor enough Ether to send 10 ether to the contract
        vm.deal(actor, 10 ether + 1 ether);

        // Record collector's balance before the call
        uint256 collectorBalanceBefore = address(collector).balance;

        // Make the contract send funds to collector instead of msg.sender by using the collector as the caller.
        // The reference transfers to msg.sender; the mutant transfers nothing.
        vm.prank(address(collector));
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "call should succeed");

        uint256 collectorBalanceAfter = address(collector).balance;

        bool condition = blockNumMod % 15 == 0;
        // If block number divisible by 15, balance of collector must increase by the contract's entire balance,
        // which is at least 10 ether. The mutant never transfers, so collector balance stays the same.
        // The universal rule: after a successful fallback call with 10 ether and block.number % 15 == 0,
        // the caller's ETH balance must strictly increase.
        // For the buggy version, this condition will fail when blockNumMod % 15 == 0.
        // For the reference, it holds for every such call.
        assertTrue(!condition || collectorBalanceAfter > collectorBalanceBefore);
    }
}

