pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 blockNumberMod, uint256 warp1, uint256 warp2) public {
        // Ensure block.number % 15 == 0 for the second call: we make blockNumberMod a multiple of 15 offset.
        uint256 baseBlock = uint256(block.number);
        // We need block.number for the second call to be such that (baseBlock + 2) % 15 == 0.
        // To avoid restricting the fuzzer too much, we assume blockNumberMod is in [0,14] and compute a warp1
        // that ensures the condition. But we want the fuzzer to search. We'll use assume to restrict only to valid mods.
        vm.assume(blockNumberMod < 15);

        // We'll do two calls:
        // Call 1: sets pastBlockTime, warps to warp1, sends 10 ether from a user.
        // Call 2: warps to warp2 > warp1, sends 10 ether, block.number must satisfy % 15 == 0.
        vm.assume(warp2 > warp1);

        // Set block number for call 2 to satisfy condition.
        // We roll to a block number that is 15 * N + blockNumberMod, so that after two blocks (calls) we get a mod that we can control.
        // Simplification: set block.number to any value, then after two transactions the mod is (initial + 2) % 15.
        // Let the fuzzer supply warp1, warp2 as timestamps, and blockNumberMod as the desired modulo 15 for the second call's block.
        // We'll roll to a block number such that after two calls, block.number % 15 == 0.
        // Desired: (block.number_call2) % 15 == 0.
        // block.number_call2 = currentBlock + 2.
        // So we need (currentBlock + 2) % 15 == 0 => currentBlock % 15 == 13.
        // To give fuzzer more power, we can roll to a block number where currentBlock % 15 == blockNumberMod, and then adjust if needed.
        // Let's set: currentBlock % 15 = blockNumberMod.
        // Then after two calls, mod = (blockNumberMod + 2) % 15.
        // We want (blockNumberMod + 2) % 15 == 0 => blockNumberMod = 13.
        // That would hardcode. Instead, we can roll to a block number such that after one call, we are at a specific mod,
        // then the second call's block is that block+1. We need more flexibility.
        // Approach: Use vm.roll to set a base block, then after 2 transactions, the second tx's block is base+2.
        // We want (base+2) % 15 == 0, so base % 15 == 13. Hard-coded.
        // Alternative: We'll let the fuzzer provide any blockNumberMod, and we'll roll to a block number such that
        // block.number for the second call = some large multiple of 15 + blockNumberMod, but we need it to be exactly 0 mod 15.
        // So we can only accept blockNumberMod = 0. Not good.

