pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum) public {
        vm.assume(blockNum < type(uint256).max / 2);
        vm.roll(blockNum);
        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.fallback{value: 10 ether}();
        assertTrue(address(c).balance == 0);
    }
